难点三：上下文窗口溢出 问题描述 长对话或复杂任务会导致： Prompt + 历史对话 + 工具描述 + 中间结果 = 超过Token限制 GPT-4: 128K tokens Claude: 200K tokens 一次复杂任务可能消耗50K+ tokens → 超出限制或成本过高 解决方案 方案1：智能压缩上下文 from langchain.memory import ConversationSummaryBufferMemory memory = ConversationSummaryBufferMemory( llm=llm, max_token_limit=4000, # 保留最近4000 tokens moving_summary_buffer="", # 旧的对话自动总结 ) # 效果： # 旧对话："用户询问了天气、新闻、股票...共20轮对话" # ↓ 总结为 # "用户主要关心北京天气（晴）、今日新闻（AI发展）、股票（上涨）" 方案2：分层记忆 class HierarchicalMemory: def init(self): self.recent_memory = [] # 最近3轮，完整保留 self.mid_term_memory = [] # 中期10轮，保留关键信息 self.long_term_memory = vectorstore # 长期，向量检索 def add(self, message): self.recent_memory.append(message) if len(self.recent_memory) > 3: # 移到中期记忆，提取关键信息 old_message = self.recent_memory.pop(0) key_info = extract_key_info(old_message) self.mid_term_memory.append(key_info) if len(self.mid_term_memory) > 10: # 移到长期记忆，存入向量库 old_info = self.mid_term_memory.pop(0) self.long_term_memory.add_texts([old_info]) def get_context(self, query): # 组合三层记忆 recent = "
".join(self.recent_memory) mid = "
".join(self.mid_term_memory) relevant = self.long_term_memory.similarity_search(query, k=2) return f"{recent}

相关历史：{mid}
{relevant}" 方案3：动态工具加载 #不要一次性加载所有工具 all_tools = { "search": search_tool, "calculator": calc_tool, "database": db_tool, "api": api_tool, # ... 50个工具 } # 根据任务动态选择工具 def select_tools(task): # 分析任务需要哪些类别的工具 if "搜索" in task or "查询" in task: return [all_tools["search"]] elif "计算" in task: return [all_tools["calculator"]] # ... # 默认返回最常用的5个工具 return list(all_tools.values())[:5] # 创建Agent时只加载需要的工具 tools = select_tools(user_input) agent = create_agent(llm, tools)

案例二：代码生成Agent 需求分析 功能：根据自然语言描述生成代码 流程： 理解需求 设计方案 生成代码 测试代码 修复bug（如果有） 添加注释和文档 完整实现 from langchain.agents import Tool import subprocess import tempfile import os class CodeGenerationAgent : def init ( self ): self .llm = ChatOpenAI(model= "gpt-4" , temperature= 0 ) # 定义工具 self .tools = [ Tool( name= "GenerateCode" , func= self ._generate_code, description= "生成Python代码" ), Tool( name= "TestCode" , func= self ._test_code, description= "测试代码是否可以运行" ), Tool( name= "FixBug" , func= self ._fix_bug, description= "修复代码中的bug" ), ] def _generate_code ( self, requirement: str ) -> str : """生成代码""" prompt = f""" 请根据以下需求生成Python代码： 需求： {requirement} 要求： 1. 代码要清晰、可读 2. 添加必要的注释 3. 包含错误处理 4. 包含使用示例 请输出完整的可运行代码。 """ response = self .llm.invoke(prompt) code = self ._extract_code(response.content) return code def _test_code ( self, code: str ) -> dict : """测试代码""" # 创建临时文件 with tempfile.NamedTemporaryFile( mode= 'w' , suffix= '.py' , delete= False ) as f: f.write(code) temp_file = f.name try : # 运行代码 result = subprocess.run( [ 'python' , temp_file], capture_output= True , text= True , timeout= 5 ) if result.returncode == 0 : return { "success" : True , "output" : result.stdout, } else : return { "success" : False , "error" : result.stderr, } except subprocess.TimeoutExpired: return { "success" : False , "error" : "代码执行超时" } finally : os.unlink(temp_file) def _fix_bug ( self, code: str , error: str ) -> str : """修复bug""" prompt = f""" 以下代码有错误： 代码： ```python {code} ``` 错误信息： {error} 请修复这个bug并返回完整的正确代码。 """ response = self .llm.invoke(prompt) fixed_code = self ._extract_code(response.content) return fixed_code def _extract_code ( self, text: str ) -> str : """从回复中提取代码""" # 提取```python...```之间的内容 import re pattern = r"```python
(.*?)```" match = re.search(pattern, text, re.DOTALL) if match : return match .group( 1 ).strip() else : return text.strip() def generate ( self, requirement: str , max_attempts= 3 ): """完整的代码生成流程""" print ( f"📝 需求： {requirement} 
" ) # 步骤1：生成代码 print ( "1️⃣ 生成代码..." ) code = self ._generate_code(requirement) print ( f"生成的代码：
 {code} 
" ) # 步骤2：测试代码 print ( "2️⃣ 测试代码..." ) for attempt in range (max_attempts): test_result = self ._test_code(code) if test_result[ "success" ]: print ( "✅ 测试通过！" ) print ( f"输出： {test_result[ 'output' ]} " ) # 步骤3：添加文档 print ( "
3️⃣ 添加文档..." ) documented_code = self ._add_documentation(code) return documented_code else : print ( f"❌ 测试失败（尝试 {attempt+ 1 } / {max_attempts} ）" ) print ( f"错误： {test_result[ 'error' ]} 
" ) # 修复bug print ( "🔧 修复bug..." ) code = self ._fix_bug(code, test_result[ 'error' ]) print ( f"修复后的代码：
 {code} 
" ) # 所有尝试都失败 return { "success" : False , "message" : f"经过 {max_attempts} 次尝试仍无法生成可运行的代码" , "last_code" : code, } def _add_documentation ( self, code: str ) -> str : """添加文档字符串""" prompt = f""" 为以下代码添加详细的文档字符串（docstring）和使用说明： ```python {code} ``` 要求： 1. 每个函数都有docstring 2. 包含参数说明 3. 包含返回值说明 4. 包含使用示例 """ response = self .llm.invoke(prompt) return self ._extract_code(response.content) # 使用示例 agent = CodeGenerationAgent() result = agent.generate( """ 写一个函数，计算列表中所有数字的平方和。 要求： - 输入是一个数字列表 - 返回平方和 - 包含错误处理（如果输入不是数字） """ ) print ( "
" + "=" * 50 ) print ( "最终代码：" ) print ( "=" * 50 ) print (result) # 输出示例： # 📝 需求：写一个函数，计算列表中所有数字的平方和... # # 1️⃣ 生成代码... # 生成的代码： # def sum_of_squares(numbers): # total = 0 # for num in numbers: # total += num ** 2 # return total # # 2️⃣ 测试代码... # ✅ 测试通过！ # # 3️⃣ 添加文档... # # ================================================== # 最终代码： # ================================================== # def sum_of_squares(numbers): # """ # 计算列表中所有数字的平方和。 # # 参数： # numbers (list): 数字列表 # # 返回： # int/float: 所有数字的平方和 # # 示例： # >>> sum_of_squares([1, 2, 3]) # 14 # """ # ...

案例三：数据分析Agent 需求分析 场景：自动分析Excel数据 功能： 读取Excel文件 数据清洗和预处理 统计分析（均值、中位数等） 生成可视化图表 输出分析报告 完整实现 import pandas as pd import matplotlib.pyplot as plt class DataAnalysisAgent : def analyze ( self, file_path: str , question: str ): """ 分析数据并回答问题 参数： file_path: Excel文件路径 question: 分析问题 """ # 1. 读取数据 print ( "📊 读取数据..." ) df = pd.read_excel(file_path) print ( f"数据形状： {df.shape} " ) print ( f"列名： {df.columns.tolist()} 
" ) # 2. 让Agent分析应该做什么 print ( "🤔 分析问题..." ) analysis_plan = self ._plan_analysis(df, question) print ( f"分析计划：
 {analysis_plan} 
" ) # 3. 执行分析 print ( "⚙️ 执行分析..." ) results = self ._execute_analysis(df, analysis_plan) # 4. 生成报告 print ( "📝 生成报告..." ) report = self ._generate_report(results, question) return report def _plan_analysis ( self, df, question ): """制定分析计划""" prompt = f""" 数据集信息： - 形状： {df.shape} - 列名： {df.columns.tolist()} - 前5行数据： {df.head().to_string()} 问题： {question} 请制定分析计划（JSON格式）： {{ "steps": [ {{"action": "统计描述", "columns": ["..."]}}， {{"action": "分组分析", "group_by": "...", "agg": "..."}}, {{"action": "可视化", "chart_type": "...", "x": "...", "y": "..."}} ] }} """ response = self .llm.invoke(prompt) return json.loads(response.content) def _execute_analysis ( self, df, plan ): """执行分析步骤""" results = {} for step in plan[ "steps" ]: action = step[ "action" ] if action == "统计描述" : results[ "统计" ] = df[step[ "columns" ]].describe() elif action == "分组分析" : results[ "分组" ] = df.groupby(step[ "group_by" ]).agg(step[ "agg" ]) elif action == "可视化" : self ._create_chart(df, step) results[ "图表" ] = "已生成" return results #使用 agent = DataAnalysisAgent() report = agent.analyze( "sales_data.xlsx" , "分析各地区的销售情况，找出销售最好的3个地区" )
